package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"path/filepath"
)

func countLines(input io.Reader) (int, error) {
	scanner := bufio.NewScanner(input)
	count := 0
	for scanner.Scan() {
		count++
	}
	return count, scanner.Err()
}

func main() {
	dir, err := os.MkdirTemp("", "layers-demo")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(dir)
	name := filepath.Join(dir, "items.txt")
	if err := os.WriteFile(name, []byte("one\ntwo\n"), 0o600); err != nil {
		panic(err)
	}
	file, err := os.Open(name)
	if err != nil {
		panic(err)
	}
	count, err := countLines(file)
	if err != nil {
		file.Close()
		panic(err)
	}
	if err := file.Close(); err != nil {
		panic(err)
	}
	fmt.Println(count)
}
