package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"os"
	"path/filepath"
)

func main() {
	dir, err := os.MkdirTemp("", "choice-demo")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(dir)
	name := filepath.Join(dir, "data.txt")
	if err := os.WriteFile(name, []byte("a\nb\n"), 0o600); err != nil {
		panic(err)
	}

	all, err := os.ReadFile(name)
	if err != nil {
		panic(err)
	}
	fmt.Println("ReadFile bytes:", len(all))

	scanner := bufio.NewScanner(bytes.NewReader(all))
	lines := 0
	for scanner.Scan() {
		lines++
	}
	if err := scanner.Err(); err != nil {
		panic(err)
	}
	fmt.Println("Scanner lines:", lines)

	var copied bytes.Buffer
	n, err := io.Copy(&copied, bytes.NewReader(all))
	if err != nil {
		panic(err)
	}
	fmt.Println("Copy bytes:", n)
}
