```go
package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"strings"
)

func numberLines(dst io.Writer, src io.Reader) error {
	scanner := bufio.NewScanner(src)
	line := 1
	for scanner.Scan() {
		if _, err := fmt.Fprintf(dst, "%d: %s\n", line, scanner.Text()); err != nil {
			return err
		}
		line++
	}
	return scanner.Err()
}

func main() {
	var output bytes.Buffer
	err := numberLines(&output, strings.NewReader("red\nblue\n"))
	if err != nil {
		panic(err)
	}
	fmt.Print(output.String())
}
